+    fn ella_dock_wide_matches_the_dlm_capture() -> Result {
+        use super::DockWideStep::*;
+        let want = [
+            SetMode(0),         // vendor #86
+            Marker(0, 0x2f, 1), // #87
+            Marker(0, 0x2e, 3), // #88
