+            Marker(0, 0x2f, 1), // #97
+            Marker(0, 0x2e, 0), // #98, the last record before pixels
+            Carrier(0),         // #99
+            Stream(0, 2),       // #99..#227, the first connector streaming
+            Marker(1, 0x2f, 1), // #229
+            Marker(0, 0x2f, 0), // #247
+            Stream(0, 2),       // #248..#429
+            Marker(1, 0x2e, 0), // #431, the second connector's sink up behind a running stream
