+            // sink half raised.
+            Marker(1, 0x2f, 1), // #737
+            Stream(1, 2),       // #738..#742, two more carrier frames
+            Poll,               // #743
+            Marker(1, 0x2e, 0), // #744
+            Poll,               // #745
