+        // says 699.50 MHz where DLM's wire value rounds to its 10 kHz unit (699.49), so a ceiling
+        // taken from DLM's rounding would prune this mode by 10 kHz. It must not.
+        assert!(
+            mode.clock() as u32
+                <= profile::PROFILE_NAVARRO
+                    .capabilities
