 {
 	u32 *dummy_page_virt;
@@ -256,6 +265,13 @@ int panthor_device_init(struct panthor_device *ptdev)
 
 	ptdev->phys_addr = res->start;
 
+	/* panthor_device_resume() calls enable_resets(), so we need to disable
